<?php
$statusFilter=is_string($_GET['status'] ?? null)?$_GET['status']:'';
if(!in_array($statusFilter,['Diproses','Dikemas','Dikirim','Selesai','Dibatalkan'],true))$statusFilter='';
if($statusFilter){$st=db()->prepare('SELECT o.*,u.name customer FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.status=? ORDER BY o.id DESC');$st->bind_param('s',$statusFilter);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}
else $rows=qall('SELECT o.*,u.name customer FROM orders o LEFT JOIN users u ON u.id=o.user_id ORDER BY o.id DESC');
$deleteId=(int)($_GET['delete'] ?? 0);$deleteOrder=null;
foreach($rows as $row)if((int)$row['id']===$deleteId)$deleteOrder=$row;
?>
<nav class="erp-order-filters" aria-label="Filter status pesanan"><a href="?page=admin&tab=orders" <?= $statusFilter===''?'aria-current="page"':'' ?>>Semua</a><?php foreach(['Diproses','Dikemas','Dikirim','Selesai','Dibatalkan'] as $status): ?><a href="?page=admin&tab=orders&status=<?= urlencode($status) ?>" <?= $statusFilter===$status?'aria-current="page"':'' ?>><?= e($status) ?></a><?php endforeach; ?></nav>
<?php if($deleteOrder): ?>
<section class="erp-card erp-form-narrow"><div class="erp-card-head"><div><h2>Hapus Pesanan <?= e($deleteOrder['order_code']) ?></h2><p>Pesanan, detail produk, dan tracking akan dihapus permanen. Catatan keuangan dan audit stok tetap tersimpan.</p></div></div>
<form method="post" class="erp-form"><input type="hidden" name="action" value="admin_order_delete"><input type="hidden" name="order_id" value="<?= $deleteId ?>"><input type="hidden" name="csrf" value="<?= e(admin_management_csrf()) ?>">
<?php if($deleteOrder['stock_state']==='deducted' && !in_array($deleteOrder['status'],['Dikirim','Selesai'],true)): ?><label class="management-check"><input type="checkbox" name="restore_stock" checked> Kembalikan stok produk dari pesanan ini</label><?php else: ?><p>Stok tidak dikembalikan karena sudah dikirim atau sebelumnya sudah dilepas.</p><?php endif; ?>
<label>Ketik nomor pesanan untuk konfirmasi<input name="confirmation" required autocomplete="off" placeholder="<?= e($deleteOrder['order_code']) ?>"></label><button class="erp-btn erp-btn-danger">Hapus Permanen</button><a href="?page=admin&tab=orders">Batal</a></form></section>
<?php endif; ?>
<?php $manualPending=qall("SELECT id,order_code,total,payment_method FROM orders WHERE payment_provider='manual' AND payment_method<>'COD' AND payment_status<>'paid' AND status<>'Dibatalkan' ORDER BY id DESC"); ?>
<?php if($manualPending): ?><section class="erp-card"><div class="erp-card-head"><div><h2>Verifikasi Pembayaran Manual</h2><p>Konfirmasi hanya setelah nominal transfer/QRIS manual benar-benar diterima.</p></div></div><?php foreach($manualPending as $payment): ?><form method="post" class="erp-inline"><span><?= e($payment['order_code']) ?> · <?= e($payment['payment_method']) ?> · <?= rupiah($payment['total']) ?></span><input type="hidden" name="action" value="admin_manual_payment_confirm"><input type="hidden" name="csrf" value="<?= e(auth_csrf()) ?>"><input type="hidden" name="order_id" value="<?= (int)$payment['id'] ?>"><button class="erp-btn" onclick="return confirm('Konfirmasi pembayaran ini sudah diterima?')">Konfirmasi Lunas</button></form><?php endforeach; ?></section><?php endif; ?>
<section class="erp-card"><div class="erp-card-head"><div><h2>Sales Order</h2><p>Kelola status, tracking, dan hapus pesanan percobaan.</p></div></div><div class="erp-table-wrap"><table><thead><tr><th>Order</th><th>Pelanggan</th><th>Pembayaran</th><th>Total pembayaran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php if(!$rows): ?><tr><td colspan="6">Belum ada pesanan.</td></tr><?php endif; ?>
<?php foreach($rows as $o): ?><tr><td><b><?= e($o['order_code']) ?></b><small><?= e(date('d M Y H:i',strtotime($o['created_at']))) ?></small></td><td><?= e($o['customer'] ?? '-') ?></td><td><?= e($o['payment_method']) ?><?php if(($o['payment_provider']??'manual')==='midtrans'): ?><small>Sandbox Midtrans · <?= e(['pending'=>'Menunggu pembayaran','paid'=>'Sudah dibayar','expired'=>'Kedaluwarsa','failed'=>'Gagal / dibatalkan','refunded'=>'Pengembalian dana'][$o['payment_status']]??$o['payment_status']) ?></small><?php endif; ?></td><td><?= rupiah(order_payment_total($o)) ?><?php if(!empty($o['payment_unique_code'])): ?><small>Total pesanan <?= rupiah($o['total']) ?><br>Kode unik <?= str_pad((string)$o['payment_unique_code'],3,'0',STR_PAD_LEFT) ?> (+<?= rupiah($o['payment_unique_code']) ?>)</small><?php endif; ?></td><td><?= e($o['status']) ?></td><td><form method="post" class="erp-inline"><input type="hidden" name="action" value="erp_order_status"><input type="hidden" name="csrf" value="<?= e(auth_csrf()) ?>"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach(['Diproses','Dikemas','Dikirim','Selesai','Dibatalkan'] as $s): ?><option <?= $o['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button>Update</button></form><div class="management-row-actions"><a href="?page=admin&tab=tracking&edit=<?= (int)$o['id'] ?>">Edit Tracking</a><a href="?page=admin&tab=orders&delete=<?= (int)$o['id'] ?>">Hapus Pesanan</a></div></td></tr><?php endforeach; ?>
</tbody></table></div></section>
